/* Intermediate7: access patterns, immutable primary keys and verified paused-writer migration. */
(function () {
  const N=AG.aws.n,clone=x=>JSON.parse(JSON.stringify(x)),file=x=>({content:JSON.stringify(x,null,2)});
  const wrap=s=>'<div class="tbl-wrap">'+s+'</div><p class="muted">Phone par table sideways swipe karo.</p>';
  const rows=()=>[101,102,103].map((id,i)=>({cartId:'cart-'+id,status:'active',sellerId:i===1?'seller-2':'seller-1',updatedAt:1800000000+i,expiresAt:1900000000+i,total:499,version:1}));
  const fresh=()=>({cartId:'cart-104',status:'active',sellerId:'seller-1',updatedAt:1800000004,expiresAt:1900000004,total:499,version:1});
  const typed=row=>Object.fromEntries(Object.entries(row).map(([k,v])=>[k,typeof v==='number'?{N:String(v)}:{S:v}]));
  const seed=()=>({region:'ap-south-1',tables:[{name:'carts-v1',tableId:'11111111-1111-4111-8111-111111111111',partitionKey:'status',sortKey:'cartId',attributeTypes:{status:'S',cartId:'S'},billing:'PAY_PER_REQUEST',status:'ACTIVE',items:rows()}]});
  const tab=(s,name='carts-v2')=>(s.account.tables||[]).find(t=>t.name===name);
  const equalRows=(a,b)=>Array.isArray(a)&&a.length===b.length&&b.every(row=>a.some(x=>Object.keys(x).length===Object.keys(row).length&&Object.entries(row).every(([k,v])=>x[k]===v)));
  function preserved(s){const t=tab(s,'carts-v1');return !!t&&t.tableId==='11111111-1111-4111-8111-111111111111'&&t.partitionKey==='status'&&t.sortKey==='cartId'&&t.billing==='PAY_PER_REQUEST'&&equalRows(t.items,rows())&&(s.account.tables||[]).length===2;}
  function schemaReady(s){const t=tab(s);return !!t&&t.partitionKey==='cartId'&&!t.sortKey&&t.attributeTypes?.cartId==='S'&&t.billing==='PAY_PER_REQUEST'&&t.status==='ACTIVE';}
  function indexReady(s){const t=tab(s),i=t?.gsis?.find(i=>i.name==='bySeller');return !!i&&t.gsis.length===1&&i.partitionKey==='sellerId'&&i.sortKey==='updatedAt'&&i.projection.ProjectionType==='ALL'&&i.status==='ACTIVE'&&t.attributeTypes.sellerId==='S'&&t.attributeTypes.updatedAt==='N';}
  function resultReady(s){const t=tab(s),r=t?.lastRead;return !!r&&r.op==='query'&&r.index==='bySeller'&&!r.consistent&&!r.hasMore&&r.revision===(t.revision||0)&&equalRows(r.items,[rows()[0],rows()[2],fresh()]);}
  const SOLUTION=[
    'aws dynamodb create-table --table-name carts-v2 --attribute-definitions AttributeName=cartId,AttributeType=S --key-schema AttributeName=cartId,KeyType=HASH --billing-mode PAY_PER_REQUEST',
    'aws dynamodb wait table-exists --table-name carts-v2',
    'aws dynamodb batch-write-item --request-items file://backfill.json',
    'aws dynamodb update-table --table-name carts-v2 --attribute-definitions AttributeName=sellerId,AttributeType=S AttributeName=updatedAt,AttributeType=N --global-secondary-index-updates file://seller-index.json',
    'aws dynamodb wait table-exists --table-name carts-v2',
    'aws dynamodb describe-table --table-name carts-v2',
    'aws dynamodb update-continuous-backups --table-name carts-v2 --point-in-time-recovery-specification PointInTimeRecoveryEnabled=true,RecoveryPeriodInDays=35',
    'aws dynamodb update-time-to-live --table-name carts-v2 --time-to-live-specification Enabled=true,AttributeName=expiresAt',
    'aws dynamodb describe-time-to-live --table-name carts-v2',
    "aws dynamodb put-item --table-name carts-v2 --item file://new-cart.json --condition-expression 'attribute_not_exists(cartId)'",
    "aws dynamodb put-item --table-name carts-v2 --item file://duplicate-cart.json --condition-expression 'attribute_not_exists(cartId)'",
    `aws dynamodb query --table-name carts-v2 --index-name bySeller --key-condition-expression '#s = :s' --expression-attribute-names '{"#s":"sellerId"}' --expression-attribute-values '{":s":{"S":"seller-1"}}'`
  ];
  const TASKS=[
    {text:'Original three carts/attributes preserved in carts-v1; only required v2 added',check:preserved},
    {text:'Separate carts-v2: cartId String HASH, no sort key, PAY_PER_REQUEST, ACTIVE',check:schemaReady},
    {text:'All three backfilled carts plus correct cart-104, no missing/extra attributes or items',check:s=>equalRows(tab(s)?.items,[...rows(),fresh()])},
    {text:'bySeller GSI ACTIVE: sellerId String HASH + updatedAt Number RANGE, ALL projection',check:indexReady},
    {text:'PITR enabled with 35-day recovery window; TTL expiresAt status ENABLED',check:s=>!!tab(s)?.pitr?.enabled&&tab(s).pitr.days===35&&tab(s).ttl?.attribute==='expiresAt'&&tab(s).ttl.status==='ENABLED'},
    {text:'Duplicate cart-104 total 0 condition rejected and existing total 499 preserved',check:s=>{const t=tab(s),c=t?.lastCondition;return !!c&&!c.applied&&c.key.cartId==='cart-104'&&c.attempted.total===0&&c.existing.total===499&&c.revision===(t.revision||0)&&t.items.some(x=>x.cartId==='cart-104'&&x.total===499);}},
    {text:'Final current GSI query returns exactly three seller-1 carts, no more pages',check:resultReady}
  ];
  const FILES={'backfill.json':file({'carts-v2':rows().map(row=>({PutRequest:{Item:typed(row)}}))}),'seller-index.json':file([{Create:{IndexName:'bySeller',KeySchema:[{AttributeName:'sellerId',KeyType:'HASH'},{AttributeName:'updatedAt',KeyType:'RANGE'}],Projection:{ProjectionType:'ALL'}}}]),'new-cart.json':file(typed(fresh())),'duplicate-cart.json':file(typed({...fresh(),total:0}))};
  function Q(q,correct,wrong,answer,explain){const choices=wrong.slice();choices.splice(answer,0,correct);return {q,choices,answer,explain};}
  function plan(k){const readUnits=Math.ceil(k.kb/4)*.5,writeUnits=Math.ceil(k.kb),baseR=k.reads*readUnits,baseW=k.writes*writeUnits,peakR=baseR*k.peak,peakW=baseW*k.peak,scale=[1,k.peak,k.peak/0.7][k.capacity],rcu=Math.ceil(baseR*scale),wcu=Math.ceil(baseW*scale),ondemand=(baseR*.000000125+baseW*.000000625)*3600*(22+2*k.peak)*30,provisioned=(rcu*.00013+wcu*.00065)*720,bestProvisioned=(Math.ceil(peakR)*.00013+Math.ceil(peakW)*.00065)*720,cheapest=Math.min(ondemand,bestProvisioned),cost=k.mode===0?ondemand:provisioned,capacityOK=k.mode===0||rcu>=peakR&&wcu>=peakW,share=k.key===0?1:.1,hot=peakR*share>3000||peakW*share>1000,valid=k.reads>=300&&k.writes>=150&&k.kb>=5&&k.peak>=3;return {baseR,baseW,peakR,peakW,rcu,wcu,ondemand,provisioned,cheapest,cost,hot,capacityOK,valid,ok:valid&&!hot&&capacityOK&&cost<=cheapest+.001};}
  AG.registerLevels('intermediate',[{
    id:'dynamodb',icon:'📊',title:'DynamoDB — access patterns, safe migration aur correctness',badge:'NoSQL Nayak',
    objectives:['<b>Model:</b> access patterns first; primary key versus index','<b>Capacity:</b> rounded read/write units, hot keys and current prices','<b>Consistency:</b> table/LSI versus GSI; Query versus Scan','<b>Correctness:</b> conditional writes and atomic transactions','<b>Operations:</b> verified backfill, PITR, TTL and replica trade-offs','<b>Choice:</b> DynamoDB versus SQL, S3 and cache'],
    hook:{when:'SHOPKARO · NATIONAL MAHASALE CARTS · FICTIONAL COURSE STORY',title:'“Table mein capacity bachi hai, cart writes phir throttle kyun?”',text:'Eight-person ShopKaro team moves carts from a contended SQL path to DynamoDB. Ravi chooses status as HASH and cartId as RANGE; most requests hit active carts. Sale-time telemetry points to concentrated partition traffic. Neha asks for a better key, a safe migration and proof that retries cannot overwrite a cart. Choosing NoSQL alone does not fix an access pattern.'},
    steps:[
      {q:'Table, item aur primary key ka exact model kya hai?',analogy:'Almirah drawer label partition key jaisa hai; drawer ke files ka ordered label sort key jaisa hai. Full address drawer plus file hai. Storage engine ka physical shelf layout analogy se guarantee nahi hota.',body:'<p>Table stores items with flexible non-key attributes. Primary key is either HASH alone or HASH + RANGE; the complete key is unique. With composite key, many items may share HASH as long as RANGE differs. Item limit400KB includes UTF-8 attribute names and values.</p>',points:['carts-v1 has status + cartId. active/cart-101 and active/cart-102 are different items. GetItem must supply both key elements with correct S/N types. S means String; N is a decimal string on the wire.','Primary key schema is immutable. UpdateTable cannot rename status into cartId. Create a new table, migrate with reconciliation and cut over safely; preserve rollback path.','Same logical partition key groups an item collection; physical partition placement and adaptive splitting are service-managed. High cardinality helps only when traffic is distributed; one extremely popular cart can still be hot.'],code:`aws dynamodb get-item --table-name carts-v1 --key '{"status":{"S":"active"},"cartId":{"S":"cart-101"}}'`,asli:'Action: list three access patterns before schema: cart by ID, seller carts by time, create cart without overwrite. Terminal starts from a paused-writer fixture, so the provided three-item backfill is stable.'},
      {q:'Access patterns pehle kyun; single-table kab useful?',analogy:'Courier routing map parcels receive karne se pehle banti hai. Har delivery ke baad saare parcels scan karna efficient lookup nahi. One warehouse versus separate warehouses team boundaries aur delivery routes se decide karo.',body:wrap('<table><tr><th>Requirement</th><th>Candidate</th><th>Trade-off</th></tr><tr><td>Get cart by cartId</td><td>cartId HASH</td><td>One-item key lookup</td></tr><tr><td>Seller carts in time order</td><td>sellerId + updatedAt GSI</td><td>Eventual index, extra write/storage cost</td></tr><tr><td>Ad-hoc joins/reports</td><td>SQL or S3 analytics path</td><td>Do not turn every report into table Scan</td></tr></table>'),points:['Prefixes aur composite keys related entity queries colocate karte hain aur request fan-out kam kar sakte hain. Access-pattern, index aur ownership design carefully review karo; fewer tables universal objective nahi.','Multi-table design can simplify independent ownership, retention/security boundaries and operational changes. DynamoDB transactions can span supported tables in the same account/Region; transactions do not require one table.','Unknown interactive joins and changing ad-hoc queries often fit RDS/Aurora better. Bounded atomic key-based operations can fit DynamoDB, including some financial ledgers with carefully designed invariants. No blanket “banking means SQL only” rule.'],code:'aws dynamodb create-table --table-name carts-v2 --attribute-definitions AttributeName=cartId,AttributeType=S --key-schema AttributeName=cartId,KeyType=HASH --billing-mode PAY_PER_REQUEST\naws dynamodb wait table-exists --table-name carts-v2\ncat backfill.json\naws dynamodb batch-write-item --request-items file://backfill.json',asli:'Action: terminal uses a simple separate cart table and one explicit seller access pattern. Production sellerId can itself become hot; design high-volume seller bucketing and merge-query cost from measured traffic.'},
      {q:'Hot partition ko more total capacity kyun solve nahi karti?',analogy:'Market mein ten counters khaali hain par customers ek counter par line mein hain. Total staff aur busiest counter ki capacity alag limits hain. Extra staff tab useful jab requests distribute ho sakti hain.',body:'<p>Each physical partition is designed for up to3,000 read units/s and1,000 write units/s. For up-to4KB items that means3,000 strong or6,000 eventual reads/s; up-to1KB standard writes use one write unit. Larger items and transactional requests consume more units.</p>',points:['Uniform request distribution matters as much as key cardinality. Adaptive capacity can isolate hot items or rebalance activity within table/partition limits; no promise that one logical key always maps to one forever-fixed physical partition.','On-demand still has warm/scaling properties, service quotas, optional maximum-throughput caps and hot-partition limits. Sudden traffic beyond twice previous peak within30minutes can throttle; prewarm/ramp when needed. Provisioned auto scaling responds over time, not instantly at sale start.','Write sharding spreads a hot logical workload with controlled suffixes; readers may need parallel queries and merge/deduplication. Preserve ordering, idempotency and per-entity invariants; random suffix is not free correctness.'],asli:'Action: inspect throttling reasons, key-level Contributor Insights and consumed/provisioned metrics. Planner declares measured hottest-partition fractions for the fixture; planner does not predict AWS hash placement.'},
      {q:'Query, Scan aur read consistency mein kya difference?',analogy:'Query labelled drawer kholta hai; Scan almirah ke shelves padhta hai. Baad mein unwanted pages discard karne se shelves padhne ki mehnat refund nahi hoti.',body:wrap('<table><tr><th>Operation</th><th>What to supply</th><th>Important boundary</th></tr><tr><td>GetItem</td><td>Full primary key</td><td>Missing item returns empty object</td></tr><tr><td>Query</td><td>HASH equality, optional RANGE condition</td><td>Key selection before reading; pagination</td></tr><tr><td>Scan</td><td>Table/index traversal</td><td>Filter after read; expensive at scale</td></tr></table>'),points:['Query and Scan evaluate up to1MB per page before FilterExpression. Continue LastEvaluatedKey even if Count0. Filter/Projection do not reduce base reads charged; query keys should match the actual access pattern. Scan ConsistentRead does not create whole-table snapshot isolation.','Tables and LSIs can use eventual or strongly consistent reads. GSIs and DynamoDB Streams support eventual reads. A strong read on a GSI is a ValidationException, not a way to wait for index propagation.','Round item read size up to4KB units; eventual reads consume half of strong units. Round standard writes up to1KB. A5KB item uses ceil(5/4)=2 strong read units or1 eventual read unit. Transactions consume2× corresponding standard strong-read/write units.'],code:`aws dynamodb query --table-name carts-v1 --key-condition-expression '#s = :s' --expression-attribute-names '{"#s":"status"}' --expression-attribute-values '{":s":{"S":"active"}}'`,asli:'Action: status is a reserved word; use #s alias rather than inventing --partition-key. Expect all matching carts, inspect Count/ScannedCount and paginate. Final mission queries bySeller and checks actual rows, not command history.'},
      {q:'GSI aur LSI kab choose karun?',analogy:'Book ka second index alternative lookup deta hai. A new surname index original page number change nahi karta. Index update aur main text update ke visibility contracts alag ho sakte hain.',body:wrap('<table><tr><th>Property</th><th>GSI</th><th>LSI</th></tr><tr><td>Key</td><td>Alternative HASH, optional RANGE</td><td>Same table HASH, alternative RANGE</td></tr><tr><td>Create</td><td>At creation or later</td><td>Only at table creation</td></tr><tr><td>Reads</td><td>Eventual only</td><td>Eventual or strong</td></tr><tr><td>Capacity</td><td>Separate provisioned read/write capacity</td><td>Shares table capacity</td></tr><tr><td>Quota/limit</td><td>20/table default adjustable</td><td>5/table;10GB item collection limit</td></tr></table>'),points:['GSI inherits table billing mode. Provisioned GSI write capacity can backpressure base-table writes. Projection ALL stores all attributes; KEYS_ONLY/INCLUDE can reduce index storage and write cost, but GSI cannot fetch omitted attributes from the base table automatically.','Sparse indexes contain items with required index key attributes. Invalid index key types/size can cause index-key violations during real backfill; monitor backfill and use AWS diagnostics. Simulator rejects incompatible fixtures rather than modeling partial violation repair.','Base-table reads/writes remain available during online GSI build. TableStatus ACTIVE is not enough for a newly built GSI. Wait for IndexStatus ACTIVE, then verify required query results. GSI immediate visibility after a write is never guaranteed; read-your-write-critical check should use base-table strong read.'],code:'aws dynamodb update-table --table-name carts-v2 --attribute-definitions AttributeName=sellerId,AttributeType=S AttributeName=updatedAt,AttributeType=N --global-secondary-index-updates file://seller-index.json\naws dynamodb wait table-exists --table-name carts-v2\naws dynamodb describe-table --table-name carts-v2\naws dynamodb query --table-name carts-v2 --index-name bySeller --key-condition-expression \'#s = :s\' --expression-attribute-names \'{"#s":"sellerId"}\' --expression-attribute-values \'{":s":{"S":"seller-1"}}\'',asli:'Action: read seller-index.json with cat; expect bySeller sellerId HASH + updatedAt Number RANGE, Projection ALL. Simulator uses deterministic observation steps for readiness, not elapsed AWS backfill time.'},
      {q:'On-demand versus provisioned ka bill kaise compare karun?',analogy:'Metered taxi per trip charge karti hai; monthly bus contract reserved seats ka charge leta hai. Unknown peak mein flexibility valuable hai, steady load mein reserved utilization matter karta hai. One fixed price ratio every workload ko explain nahi karta.',body:'<p>Approx US East Standard table gross list prices checked2026-10-26: on-demand read$0.125/million read units, write$0.625/million write units. Provisioned$0.00013/RCU-hour and$0.00065/WCU-hour. ₹88/$1. These rates exclude free allowances/credits, storage, indexes, backup, replication and transfer.</p>',points:['Example:5KB item needs1 eventual read unit and5 write units.300 reads/s +150 writes/s at peak3× need900 read units/s and2,250 write units/s. Provisioned capacity must meet peak or a tested scaling/prewarming plan; an average-only capacity setting can throttle.','Planner models22hours/day base +2hours/day peak over30days. Compare metered volume against fixed peak provisioned capacity; 70% utilization headroom costs extra. Real auto-scaling schedules/lag, minimums and discounts require a fuller estimate.','Current on-demand is the default recommended throughput option in AWS guidance. Stable measured workload can still favor provisioned economics; run the calculator. No stale “on-demand always2.5×” rule. Standard-IA has a different storage/request trade-off.'],asli:'Action: keep the declared minimum workload300reads/s, 150writes/s, 5 KB,3×peak. Choose capacity mode plus distribution that meets peak at the lower modeled gross cost; reducing required traffic cannot win.'},
      {q:'Retries, expiry aur recovery ko correct kaise rakhun?',analogy:'Receipt par unique order number duplicate billing rok sakta hai; stock aur order ek sealed bundle mein commit ho sakte hain. Expiry sticker, change diary aur recovery archive teen different tools hain.',body:'<p>ConditionExpression is evaluated atomically with a write. attribute_not_exists(cartId) rejects overwrite for that request. Optimistic locking compares a version and writes the next version. Every writer needs the correct condition; a single conditional request installs no permanent constraint.</p>',points:['TransactWriteItems: up to100 distinct items and4MB, same account/Region; all supported actions commit or none. No two actions target the same item. BatchWriteItem:25 puts/deletes,16MB request, non-atomic batch, no per-item conditions; retry UnprocessedItems with backoff. Transaction ClientRequestToken is idempotent for10minutes, not forever.','TTL requires Number epoch seconds. Expired items may remain for days; application reads must enforce expiry. Streams retains item-level change records up to24hours, ordered per item; duplicate consumer processing still needs idempotency. Streams is not a permanent backup.','PITR has configurable1–35day window, latest restorable time typically about5minutes behind current time, and restores a new table. Shortening window does not lower PITR price. Export to S3 requires PITR, consumes no table RCUs, and suits analytics; export is not an app query index.'],code:"aws dynamodb update-continuous-backups --table-name carts-v2 --point-in-time-recovery-specification PointInTimeRecoveryEnabled=true,RecoveryPeriodInDays=35\naws dynamodb update-time-to-live --table-name carts-v2 --time-to-live-specification Enabled=true,AttributeName=expiresAt\naws dynamodb describe-time-to-live --table-name carts-v2\naws dynamodb put-item --table-name carts-v2 --item file://new-cart.json --condition-expression 'attribute_not_exists(cartId)'",asli:'Action: terminal deliberately tries duplicate-cart.json after the correct create; expect ConditionalCheckFailedException and total 499 retained. Interview tests failed atomic checkout then successful stock/order commit.'},
      {q:'Global Tables, SQL aur cache ka final decision kya hai?',analogy:'Multiple cities mein branch ledger rakhna automatic conflict-free business rule nahi deta. Replica ka consistency contract aur write ownership pehle choose karo; branch count alone safety prove nahi karta.',body:wrap('<table><tr><th>Need</th><th>Candidate</th><th>Review</th></tr><tr><td>Known key-based durable access</td><td>DynamoDB</td><td>Keys, units, invariants, indexes</td></tr><tr><td>Interactive joins and changing SQL</td><td>RDS/Aurora</td><td>Schema, connections, read/HA design</td></tr><tr><td>Large blobs/analytics exports</td><td>S3 plus suitable query service</td><td>Keep pointer/hash in item</td></tr><tr><td>Sorted-set leaderboard</td><td>Valkey/Redis-compatible cache candidate</td><td>Durability/rebuild and freshness</td></tr><tr><td>Eventual DynamoDB read acceleration</td><td>DAX candidate</td><td>Supported APIs, stale reads, extra cost</td></tr></table>'),points:['Global Tables default MREC uses asynchronous replication and per-item last-writer-wins. Local strong read does not guarantee latest remote write. Transactions are atomic only in the invoking Region; remote replicas can briefly show partial transaction effects.','MRSC provides cross-Region strong consistency with current three-Region topology:3 replicas or2 replicas + witness. Mode cannot change after creation. Current eligible Regions allow cross-continent choices; verify Region support. MRSC has no TTL, LSI or transaction operations; GSIs remain eventual.','Galti jo sab karte hain: change PK in-place; use FilterExpression as a cheaper index; equate on-demand with no throttle; use TTL as a payment deadline; expect a replica or index to enforce global uniqueness.','Production me kya hota hai: one large seller heats the GSI, backfill competes with writes, TTL-deleted records confuse replays, retries overwrite data, and cutover loses concurrent updates. Interview follow-ups: hot cart versus hot seller? How reconcile deletes? Which read needs strong consistency? What proves rollback readiness?'],asli:'Decision tree: blob>400KB → S3 pointer; ad-hoc joins → SQL; fixed key queries → DynamoDB with invariants; pure acceleration/ranking → reviewed cache. Multi-Region requirement → choose MREC/MRSC from consistency, Region, latency and feature constraints.'}
    ],
    myth:[
      {myth:'“UpdateTable se partition key change kar denge.”',sach:'Primary key immutable. Separate table, verified backfill and controlled cutover or a designed write-sharding migration chahiye.'},
      {myth:'“On-demand means no hot partitions or quotas.”',sach:'Hot-partition capacity, scaling/warm limits, optional caps and service quotas remain. Cardinality without distributed traffic is insufficient.'},
      {myth:'“FilterExpression reads kam karti hai; GSI strong read latest dega.”',sach:'Filters apply after read and do not refund capacity. GSI is eventual only; use correct key/index and base-table strong reads when required.'},
      {myth:'“DynamoDB mein useful transactions nahi; TTL exact-time delete hai.”',sach:'Transactions support100 distinct items/4MB within supported scope. TTL background deletion can lag days; application expiry still matters.'}
    ],
    playbook:{title:'Access-pattern-first — kab DynamoDB, kab alternative',use:['Durable key-value/document access with known query patterns and measured traffic','Conditional writes/optimistic locking or bounded atomic key operations','Global replicas only after choosing consistency/feature/Region contract'],avoid:['Unknown joins/ad-hoc reports on the serving table','Large binary objects inside400KB items','Exact-time expiry or globally unique business rules assumed from TTL/MREC'],how:['Write access patterns and correctness invariants','Choose full primary key and sparse/projected indexes; test hottest item/seller','Compute rounded units, peak and complete cost','Migrate with reconciliation, catch-up, controlled cutover and rollback; validate real data'],redflags:['In-place key rewrite','High total spare capacity with key-concentrated throttles','GSI created but not ACTIVE; base write mistaken for immediate index visibility','Batch treated as atomic or token treated as permanent idempotency'],rule:'Access pattern → key distribution → consistency/invariants → peak/cost → migration and recovery proof.'},
    exam:[
      {cue:'"known key access, managed high scale"',pick:'DynamoDB candidate',why:'Validate item sizes, hot keys, consistency and bounded invariants; no infinite-scale guarantee.'},
      {cue:'"eventual DynamoDB microsecond read acceleration"',pick:'DAX',why:'Cache/read APIs and freshness fit; strong reads pass through to DynamoDB.'},
      {cue:'"multi-Region active writes"',pick:'Global Tables',why:'Choose MREC/MRSC explicitly; conflicts, Regions and feature limits differ.'},
      {cue:'"expire sessions"',pick:'TTL plus application expiry check',why:'Numeric epoch seconds; deletion can lag days.'},
      {cue:'"react to item changes"',pick:'Streams with reviewed consumer',why:'24hour change log, per-item order; consumer still handles retries.'},
      {cue:'"unknown new traffic / measured steady load"',pick:'On-demand / compare provisioned',why:'Use current unit prices and peak/scaling requirements, not fixed price ratio.'},
      {cue:'"recover accidental write in configured last1–35days"',pick:'PITR restore to new table',why:'Check actual earliest/latest restorable times; enablement is not a recovery drill.'},
      {cue:'"query by another attribute"',pick:'GSI; LSI only if same HASH and creation-time design fits',why:'GSI eventual and separately costed; hot index keys can bottleneck writes.'},
      {cue:'"all-or-nothing stock plus order"',pick:'TransactWriteItems',why:'100 distinct items/4MB in one account/Region; batch writes lack transaction atomicity.'}
    ],
    stages:[
      {type:'dryrun',title:'🔬 Active cart se seller index tak',goal:'Next click par actor/state dekho; three inline decisions mein access pattern aur consistency choose karo.',nodes:[N('user',150,255,{label:'Cart API'}),N('dynamodb#old',500,120,{label:'status HASH'}),N('dynamodb#new',500,390,{label:'cartId HASH'}),N('dynamodb#index',850,255,{label:'bySeller GSI'})],edges:[{from:'user',to:'dynamodb#old'},{from:'user',to:'dynamodb#new'},{from:'dynamodb#new',to:'dynamodb#index'}],panels:[{id:'data',title:'Item / capacity'},{id:'proof',title:'Correctness / visibility'}],steps:[
        {say:'ShopKaro receives sale cart writes. The old key uses status plus cartId;950/1000 lab carts have status active. Row count shows skew, not actual throttling.',nodes:{'dynamodb#old':{tone:'busy',badge:'active traffic'}},flows:[{from:'user',to:'dynamodb#old',label:'hot key',tone:'slow'}],panels:{data:['Fixture telemetry: hot physical partition >1000 write units/s','Other physical partitions/table have spare capacity'],proof:['Source carts retained','Logical key grouping is not permanent physical placement']}},
        {say:'Contributor Insights plus throttle reason identify concentration. Adding total capacity alone cannot guarantee relief for the measured hot partition.',ask:Q('Best response to measured concentrated partition writes?','Redesign keys/shards from traffic and preserve business invariants',['Raise total capacity without reviewing the concentrated access path','Switch billing mode without checking hot partition and warm limits','Lower timeout without checking write distribution or retry effects'],1,'Key distribution addresses concentration. Extra total capacity or on-demand may still leave hot-partition limits; timeout changes neither distribution nor correctness.')},
        {say:'Ravi creates a separate cartId-keyed table. Writers are paused in this fixture. Backfill copies all attributes and compares actual rows before acceptance.',flows:[{from:'user',to:'dynamodb#new',label:'cart IDs',tone:'ok'}],nodes:{'dynamodb#old':{tone:'idle',badge:'preserved'},'dynamodb#new':{tone:'new',badge:'verified rows'}},panels:{data:['cart-101,102,103 preserved','Production needs catch-up/reconciliation for live writes'],proof:['Primary key cannot change in-place','Old table preserved for reviewed rollback']}},
        {say:'Seller listing needs another access pattern. bySeller uses sellerId HASH plus updatedAt RANGE. Real backfill must finish before querying; table ACTIVE alone is insufficient.',flows:[{from:'dynamodb#new',to:'dynamodb#index',label:'eventual',tone:'slow'}],nodes:{'dynamodb#index':{tone:'busy',badge:'CREATING → ACTIVE'}},ask:Q('Base-table write just succeeded. Seller GSI latest data guaranteed?', 'No; GSI is eventual, use base strong read for critical confirmation',['Yes; table ACTIVE makes every GSI read globally strongly consistent','Yes; ConsistentRead on GSI forces propagation before returning data','No; a GSI cannot ever show changes written after index creation'],2,'GSI is eventual. Table readiness does not promise index propagation; ConsistentRead on GSI is rejected; active GSI does receive later writes.')},
        {say:'Cart create uses attribute_not_exists(cartId). A duplicate request with total 0 fails atomically and retains total 499. The condition applies to this request, not every future writer.',panels:{proof:['First conditional create succeeds','Duplicate receives ConditionalCheckFailedException','Readback total 499, no duplicate item']},ask:Q('What does one successful conditional create establish?','That request was atomic; every other writer still needs its own condition',['The table now enforces this business rule on all future PutItem calls','Every retry is permanently deduplicated without business identity','A BatchWriteItem duplicate will inherit the previous PutItem condition'],0,'Condition belongs to the individual write. No persistent constraint is installed; idempotency needs stable identity and every relevant write path; batches do not inherit conditions.')},
        {say:'Final seller-1 query returns three correct carts after readiness/configuration checks. Moto and simulator do not prove real latency, TTL ageing, live cutover or replica convergence.',nodes:{'dynamodb#new':{tone:'ok',badge:'data verified'},'dynamodb#index':{tone:'ok',badge:'3 seller carts'}},panels:{data:['cart-101 + cart-103 + cart-104','Source rows unchanged'],proof:['PITR35 and TTL metadata enabled','No real physical throughput claim']}}
      ],lesson:'Access pattern → immutable key migration → index readiness → request-level condition → actual data proof.'},
      {type:'flowlab',title:'🎛️ Rounded units, peak aur lower gross bill',scenario:'Fixture requires at least 300 eventual reads/s, 150 standard writes/s, 5 KB items and 3×peak. Each day 22 h base + 2 h peak. Measured hottest physical partition share: concentrated100% or distributed10%. On-demand warm/table quotas assumed prepared; no actual throughput simulation.',goal:'Required workload preserve karo. Choose distribution, mode and capacity plan that meets peak at the cheaper modeled gross cost. Try 300 reads/s, 150 writes/s, 5 KB and 3×, provisioned, peak capacity and distributed traffic.',knobs:[
        {id:'reads',label:'Base eventual reads',min:100,max:300,step:100,value:300,fmt:v=>v+' /s'},
        {id:'writes',label:'Base standard writes',min:50,max:150,step:50,value:150,fmt:v=>v+' /s'},
        {id:'kb',label:'Stored item size',min:1,max:9,step:4,value:5,unit:'KB'},
        {id:'peak',label:'Two-hour daily peak',min:1,max:5,step:2,value:3,unit:'×'},
        {id:'mode',label:'Billing mode',min:0,max:1,step:1,value:1,labels:{0:'On-demand',1:'Provisioned'}},
        {id:'capacity',label:'Provisioned plan',min:0,max:2,step:1,value:0,labels:{0:'Base only',1:'Peak fixed',2:'Peak at70% utilization'}},
        {id:'key',label:'Hot partition share',min:0,max:1,step:1,value:0,labels:{0:'100% hottest',1:'10% hottest'}}
      ],model:k=>{const p=plan(k);return {readouts:[{label:'Peak required units',value:p.peakR+' read/s · '+p.peakW+' write/s',tone:'acc'},{label:'Provisioned chosen',value:p.rcu+' RCU · '+p.wcu+' WCU',tone:p.capacityOK?'ok':'bad'},{label:'On-demand gross/month',value:'approx $'+p.ondemand.toFixed(2),tone:'acc'},{label:'Provisioned gross/month',value:'approx $'+p.provisioned.toFixed(2),tone:'acc'},{label:'Chosen / required minimum',value:'approx ₹'+Math.round(p.cost*88)+' · '+(p.valid?'workload retained':'below required load'),tone:p.valid?'ok':'bad'},{label:'Hottest physical partition',value:p.hot?'exceeds declared unit limit':'within declared unit limit',tone:p.hot?'bad':'ok'}],verdict:{ok:p.ok,text:p.ok?'Peak capacity/distribution fit and lower gross cost chosen. Check real warm limits, scaling, headroom and all excluded cost meters before production.':!p.valid?'Required traffic/item/peak cannot be reduced to win.':p.hot?'Measured hot partition exceeds limit; changing total billing/capacity alone is insufficient.':!p.capacityOK?'Base-only provisioned plan cannot meet peak. Auto scaling is not instant.':'Compare fixed peak provisioned versus metered on-demand at this workload; headroom costs more.'}};},check:k=>plan(k).ok,lesson:'Read ceil(KB/4) ×0.5 for eventual; write ceil(KB/1). Prices: US East Standard approx$0.125/M read,$0.625/M write,$0.00013/RCU-h,$0.00065/WCU-h;30days/720h,₹88/$. Gross excludes free allowances, credits, storage/indexes, backups, replication, network and tax. Capacity choice is a model, not a load test.'},
      {type:'bins',title:'🗂️ Requirement ka right store',instructions:'Known access pattern, object size aur query shape se choose karo. Ranking/cache choice has a separate rebuild/durability review.',bins:[{id:'ddb',label:'DynamoDB'},{id:'sql',label:'RDS / Aurora'},{id:'s3',label:'S3'},{id:'cache',label:'Valkey / Redis-compatible cache'}],items:[
        {text:'Durable cart get by ID, known seller access pattern',bin:'ddb',explain:'Known key/index access with explicit conditions and traffic distribution.'},{text:'Changing interactive joins across orders, customers and payments',bin:'sql',explain:'Relational querying fits; transactions alone do not exclude DynamoDB.'},{text:'20MB product image with a checksum/pointer in the cart item',bin:'s3',explain:'Object bytes exceed400KB; keep metadata pointer in the serving database.'},{text:'Top100 player rank, sorted-set updates, reviewed rebuild path',bin:'cache',explain:'Sorted sets fit ranking; one game_id DynamoDB partition plus DAX is not a universal fix.'},{text:'Atomic stock decrement plus order put across two known keys',bin:'ddb',explain:'Bounded TransactWriteItems fits if all invariants and supported scope hold.'},{text:'Monthly historical Parquet exports for analytics',bin:'s3',explain:'Object analytics with suitable query service avoids serving-table scans.'}
      ]},
      {type:'fill',title:'🧩 Reserved status Query — real CLI',instructions:'Four blanks fill karo. Alias status, use typed values, query the existing composite-key source. No fake --partition-key flag.',template:`aws dynamodb {0} --table-name carts-v1 \\\n  --{1} '#s = :s' \\\n  --expression-attribute-names '{"#s":"{2}"}' \\\n  --expression-attribute-values '{":s":{"{3}":"active"}}'`,tokens:['query','key-condition-expression','status','S','scan','partition-key','sellerId','N'],blanks:[{answer:'query',explain:'Known HASH equality uses Query; Scan reads traversal pages.'},{answer:'key-condition-expression',explain:'Real CLI specifies HASH equality with this flag.'},{answer:'status',explain:'#s resolves reserved attribute name status; no literal #s field is stored.'},{answer:'S',explain:'Source status is String; Number would mismatch key type.'}]},
      {type:'triage',title:'🩺 Spare table capacity, one hot access path',symptom:'Sale telemetry reports ProvisionedThroughputExceededException. Fixture gives actual hot-partition throttle reason; schema and access frequency must be reviewed before blindly buying more capacity.',goal:'Clue commands run karo, phir root cause aur repair choose karo.',commands:[
        {cmd:'aws dynamodb describe-table --table-name carts-v1',out:'{"KeySchema":[{"AttributeName":"status","KeyType":"HASH"},{"AttributeName":"cartId","KeyType":"RANGE"}],"TableStatus":"ACTIVE"}',clue:true,note:'Most active requests share the status item collection; physical placement still needs telemetry.'},
        {cmd:'aws dynamodb describe-contributor-insights --table-name carts-v1',out:'{"ContributorInsightsStatus":"ENABLED","ContributorInsightsRuleList":["DynamoDBContributorInsights-PKC-carts-v1-fixture"]}\nDashboard fixture: active key accounts for95% of cart writes',clue:true,note:'Contributor concentration is separate evidence; API status alone does not return per-key frequencies.'},
        {cmd:'aws logs tail /shopkaro/cart-api',out:'ProvisionedThroughputExceededException ThrottlingReason=TableWriteKeyRangeThroughputExceeded; aggregateConsumed=4200/10000WCU; hottestPhysicalPartition=1350writeUnits/s',clue:true,note:'Measured partition limit exceeded despite aggregate spare capacity; synthetic course log, not Moto output.'},
        {cmd:'aws dynamodb describe-continuous-backups --table-name carts-v1',out:'{"PointInTimeRecoveryStatus":"ENABLED"}',clue:false,note:'Recovery configuration does not remove hot-partition write pressure.'}
      ],questions:[
        Q('Which evidence explains the aggregate spare-capacity paradox?','A measured hot physical partition exceeds its limit under concentrated writes',['PITR stores too many backups and consumes all table write capacity every second','The optional sort key makes every composite-key PutItem invalid on DynamoDB','A GSI strong read guarantees enough capacity for every base-table write burst'],3,'Hot partition versus aggregate capacity explains the observed reason/metrics. PITR is recovery, composite keys are valid, and GSI cannot provide strong reads or base-write capacity.'),
        Q('Which repair preserves correctness while addressing concentration?','Create a better-keyed table, reconcile data and perform reviewed cutover/rollback',['UpdateTable replaces the existing HASH key while keeping the same table data layout','Delete active carts so the table metrics stop reporting concentrated requests','Increase timeout and assume retries cannot overwrite any already-existing cart'],0,'New key design plus safe migration addresses distribution. Primary key cannot change in-place; deletion loses carts; timeout/retries without conditions do not fix the access path or invariants.')
      ]},
      {type:'terminal',title:'🖥️ Migrate carts; verify index and duplicate protection',instructions:'Writers paused. ls/cat se four files inspect karo. Numbered chunks follow karo; output mein index status aur rejected duplicate check karo.',goal:'<p><b>1 — Create/backfill:</b> carts-v2 cartId String HASH, PAY_PER_REQUEST; wait ACTIVE; batch-write backfill.json. Source carts-v1 untouched rakho.</p><p><b>2 — Seller lookup:</b> add seller-index.json using sellerId String + updatedAt Number definitions. Wait table, then describe-table: bySeller must be ACTIVE. Deterministic simulator observations represent readiness; real backfill timing differs.</p><p><b>3 — Safety:</b> PITR 35 days; TTL expiresAt enable + describe-time-to-live. Conditional new-cart.json create; duplicate-cart.json conditional retry must fail and preserve total 499.</p><p><b>4 — Evidence:</b> Query bySeller seller-1 with #s alias. Expect cart-101,103,104 with all correct attributes. Only that final current data result completes the mission.</p>',account:seed(),files:FILES,tasks:TASKS,solution:SOLUTION,hints:['Use a separate table; primary key cannot be rewritten. Inspect ls and cat backfill.json before copying.',SOLUTION.slice(0,3).join(' phir '),SOLUTION.slice(3,6).join(' phir '),SOLUTION.slice(6,9).join(' phir '),SOLUTION.slice(9).join(' phir ')],success:AG.allOf(TASKS),successText:'Three original carts and all attributes preserved; separate v2 has correct key/GSI/PITR/TTL, duplicate total 0 rejected, current seller query returns three correct carts. No live cutover, real throughput, TTL ageing or PITR restore was proven.'},
      {type:'docker',title:'🐳 Lab15 — 1,000 real local carts',project:'15-dynamodb-access-patterns',goal:'Run real CLI/SDK requests against local Moto and inspect full item equality, conditional rejection and atomic rollback. No Docker required for this lab.',why:'In-app engine is bounded. Local API execution catches syntax, typed data and emulator gaps independently of mission predicates.',steps:[
        {text:'Source local environment; read lab.py; create this run isolated v1 table.',cmd:'source ../env.sh && ../.venv/bin/python -I lab.py setup',expect:'SOURCE items1000; logical key counts active950/saved50. Generated names vary.'},
        {text:'Migrate and run GSI/PITR/TTL, duplicate and checkout exercises.',cmd:'../.venv/bin/python -I lab.py exercises',expect:'BACKFILL equalAttributes true; seller count100→101; duplicate rejected and total 499. ROLLBACK stock1/order absent; ATOMIC-COMMIT stock0/order quantity1.'},
        {text:'Delete only ledger-owned tables and verify absence.',cmd:'../.venv/bin/python -I lab.py cleanup',expect:'OWNED_TABLES_REMAIN []'}
      ],observe:Q('What does the local lab establish?', 'Actual data migration and request correctness, with explicit Moto runtime limits',['Measured AWS physical throughput and guaranteed partition placement for every key','Exact-time TTL deletion plus35days of verified point-in-time historical recovery','Cross-Region strong consistency and a production app cutover with zero data loss'],1,'Actual requests and item equality are evidence. Moto does not prove physical throughput, elapsed TTL/PITR history, global replication or live cutover. Same-token transaction replay is an observed Moto gap.')},
      {type:'quiz',title:'🎓 Access-pattern and correctness decisions',questions:[
        Q('A table uses status HASH and cartId RANGE. Need cartId HASH instead. Safe mechanism?', 'Create a separate table, reconcile backfill/live changes, then cut over with rollback',['UpdateTable changes HASH directly and automatically rehashes every existing item','Rename status inside items and assume DynamoDB also changes the table KeySchema','Delete source items before testing the new schema so writers cannot find duplicates'],2,'Primary key schema is immutable. Use a new table and migration/catch-up. Renaming item fields does not change schema; deleting source before acceptance destroys recovery.'),
        Q('A5KB item is read eventually and written once without a transaction. Units per operation?', 'One eventual read unit and five standard write units after size rounding',['Half an eventual read unit and one write unit because a request is one API call','Two eventual read units and ten write units because every operation is transactional','Five eventual read units and five write units because both round at one kilobyte'],3,'ceil(5/4)×0.5=1 eventual read unit; ceil(5/1)=5 write units. Request count alone ignores size;2× applies to transactions; read rounding is4KB, not1KB.'),
        Q('Query reads1MB before a filter discards99% of items. Which claim is accurate?', 'Filter reduces returned rows, while evaluated reads still consume their capacity',['Filter runs before physical reads, so the discarded99% incurs no read capacity','ProjectionExpression refunds the read units for every attribute omitted from output','A filtered empty page proves no matching items exist in any remaining query page'],0,'Filters/projections do not refund evaluated read capacity. Continue LastEvaluatedKey, even if Count0. Improve key selection/index; output size is not the read billing meter.'),
        Q('A seller GSI must display an order immediately after write acknowledgement. Correct contract?', 'Use base-table strong read for critical confirmation; GSI visibility is eventual',['Set ConsistentRead true on GSI to force immediate synchronization with the writer','Wait table-exists once and assume every later index write is immediately visible','Use a same-HASH GSI because matching partition keys automatically enable strong reads'],1,'GSI is eventual regardless of key similarity. Strong reads are supported on base tables/LSIs; GSI ConsistentRead is rejected. Initial table readiness does not remove later propagation lag.'),
        Q('BatchWriteItem returns UnprocessedItems after several successful puts. Appropriate handling?', 'Retry only unprocessed requests with backoff; batch is not an atomic transaction',['Retry nothing because any UnprocessedItems response rolls back every earlier put','Treat each PutRequest as conditional create because BatchWriteItem prevents overwrites','Send the full batch as one hundred actions because BatchWriteItem allows100items'],2,'Batch writes are not atomic; per-item puts/deletes may succeed while others need retry. Batch max25 actions and no conditions;100 is transaction limit. Unconditional puts may overwrite.'),
        Q('Sessions have numeric expiresAt in the past but still appear. What should the app do?', 'Enforce expiry during reads and let TTL remove eligible items asynchronously',['Assume TTL is broken because every eligible item must vanish exactly at expiresAt','Store the expiry as a formatted String so the deletion worker schedules exact timing','Disable TTL and assume a Global Table replica permanently filters expired sessions'],3,'TTL deletion may lag days. Application expiry checks are required; attribute must be Number epoch seconds. String dates and replicas do not create deadline enforcement.'),
        Q('Need atomic stock decrement and order create across two known items. Best scoped statement?', 'Use a conditional transaction; supported actions all commit or all roll back',['Use two independent PutItem calls because response order guarantees atomic commit','Use BatchWriteItem because every multi-item batch provides the same atomic isolation','Put both operations on the same stock key inside one transaction for stronger safety'],0,'TransactWriteItems supports100 distinct items/4MB in one account/Region. Separate calls and batches lack all-or-nothing semantics; multiple actions cannot target the same item.'),
        Q('MREC versus MRSC Global Tables: which statement is current?', 'MREC is async; MRSC strong replicas have three-Region topology and feature limits',['Both modes provide cross-Region atomic transactions and support TTL on every replica','Local strong reads on MREC always include the latest write from any remote Region','Changing an existing MREC table into MRSC preserves every feature without migration'],1,'MREC replication is async with local-only transaction atomicity. MRSC mode cannot be changed after creation and currently lacks TTL/LSI/transactions; GSI remains eventual. Review eligible Regions and topology.')
      ]},
    ],
    interview:{title:'Interview — invariants, hot keys aur atomic checkout',instructions:'Four trade-off questions ke baad stock1 fixture mein failed and successful transaction ka actual state prove karo.',questions:[
      Q('A million carts have distinct IDs, but one seller handles most writes. What needs review?', 'Inspect hottest item/index keys and shard only with a defined read/invariant strategy',['Declare the table safe because distinct primary keys guarantee evenly distributed activity','Add sellerId GSI without measuring seller concentration because index writes are free','Enable DAX and assume every base-table write throttle disappears through read caching'],2,'High cardinality is not uniform traffic; seller GSI can be hot. Sharding needs fan-out/invariant design. GSI writes cost capacity; DAX read caching does not distribute all writes.'),
      Q('Can a DynamoDB-backed payment-like ledger ever be appropriate?', 'Yes, for bounded key patterns with explicit atomic invariants and audited design',['No, because DynamoDB supports no atomic multi-item transaction under any configuration','Yes, because MREC replication makes every cross-Region transaction globally atomic','Yes, because a BatchWriteItem request guarantees every stock and ledger change commits'],3,'Bounded transactional key workloads can fit. DynamoDB supports transactions; MREC remote atomicity is absent; BatchWriteItem lacks transaction guarantees. Financial correctness still needs full design.'),
      Q('A real migration Scan uses ConsistentRead while writers continue. What is missing?', 'Change capture/reconciliation including deletes, catch-up and controlled cutover/rollback',['Nothing else, because strong Scan returns a single snapshot across the complete table','Only a table rename, because UpdateTable changes primary keys and names atomically','Only TTL, because expired source rows cannot change during the entire backfill interval'],0,'Strong Scan is not whole-table snapshot isolation. Live migration needs concurrent-change handling and acceptance/rollback; table key/name rewrite is unavailable; TTL is asynchronous, not a migration lock.'),
      Q('A checkout retry reuses identical ClientRequestToken. What contract should you explain?', 'AWS deduplicates within10minutes; keep business idempotency beyond the token window',['The token installs a permanent unique order constraint even after the retention window','The token requires the request payload to change on each retry to distinguish failures','Moto replay behavior proves deployed AWS never supports token-based transaction retries'],1,'Identical token retry is idempotent within10minutes; changed parameters conflict. Tokens are not permanent business constraints; observed Moto replay gap does not redefine AWS semantics.'),
      {terminal:(()=>{const transaction=n=>[{Update:{TableName:'checkout',Key:{id:{S:'SKU#kurta'}},UpdateExpression:'SET available = available - :n',ConditionExpression:'available >= :n',ExpressionAttributeValues:{':n':{N:String(n)}}}},{Put:{TableName:'checkout',Item:{id:{S:'ORDER#9001'},quantity:{N:String(n)}},ConditionExpression:'attribute_not_exists(id)'}}];
        const initial=[{id:'SKU#kurta',available:1}],solution=['aws dynamodb transact-write-items --transact-items file://too-many.json --client-request-token checkout-failed','aws dynamodb transact-write-items --transact-items file://checkout.json --client-request-token checkout-success',`aws dynamodb get-item --table-name checkout --key '{"id":{"S":"ORDER#9001"}}' --consistent-read`];
        const tasks=[{text:'Rejected quantity2 transaction preserved stock1 and absent order',check:s=>{const r=s.ddbLastFailedTransaction,t=r?.tables?.find(t=>t.name==='checkout');return !!r&&r.reasons[0]==='ConditionalCheckFailed'&&r.items?.length===2&&r.items[0].Update?.Key?.id?.S==='SKU#kurta'&&r.items[0].Update.ExpressionAttributeValues?.[':n']?.N==='2'&&r.items[1].Put?.Item?.id?.S==='ORDER#9001'&&r.items[1].Put.Item.quantity?.N==='2'&&equalRows(t?.items,initial);}}, {text:'Atomic quantity1 commit: stock0 + one order quantity1, no other rows',check:s=>{const r=s.ddbLastTransaction,t=r?.tables?.find(t=>t.name==='checkout'),expected=[{id:'SKU#kurta',available:0},{id:'ORDER#9001',quantity:1}];return !!r&&r.items?.length===2&&r.items[0].Update?.Key?.id?.S==='SKU#kurta'&&r.items[1].Put?.Item?.id?.S==='ORDER#9001'&&equalRows(t?.items,expected)&&equalRows(tab(s,'checkout')?.items,expected);}},{text:'Current strong GetItem proves actual committed ORDER#9001',check:s=>{const t=tab(s,'checkout'),r=t?.lastRead;return !!r&&r.op==='get-item'&&r.consistent&&r.revision===(t.revision||0)&&equalRows(r.items,[{id:'ORDER#9001',quantity:1}]);}}];
        return {title:'🖥️ One stock item; atomic checkout',goal:'<p>checkout table has SKU#kurta available1. cat too-many.json and checkout.json. Run aws dynamodb transact-write-items --transact-items file://too-many.json --client-request-token checkout-failed. Quantity2 must return TransactionCanceledException with unchanged data. Then aws dynamodb transact-write-items --transact-items file://checkout.json --client-request-token checkout-success commits stock0 plus ORDER#9001 quantity1. Final strong get-item of the order must return the actual committed row.</p><p>No separate stock/order writes, deleting stock or partial success qualify. Tokens are valid10minutes in the bounded fixed-clock simulator; no billing/locking latency benchmark.</p>',account:{region:'ap-south-1',tables:[{name:'checkout',partitionKey:'id',attributeTypes:{id:'S'},billing:'PAY_PER_REQUEST',status:'ACTIVE',items:initial}]},files:{'too-many.json':file(transaction(2)),'checkout.json':file(transaction(1))},solution,tasks,hints:['Quantity2 exceeds stock1: inspect transaction files and prove all-or-nothing failure before successful checkout.',...solution],success:AG.allOf(tasks),successText:'Failed quantity2 left stock/order unchanged. Quantity1 atomically committed stock0/order1; final strong read returned the real order. Moto token replay divergence and fixed-clock simulator limits remain explicit.'};})()}
    ]},
    success:['Access patterns aur immutable primary key migration explain kar sakta hoon','Rounded units, peak economics aur hot-key evidence compare kar sakta hoon','GSI/LSI consistency/projection aur Query/Scan pagination choose kar sakta hoon','Conditional writes, transactions, TTL/PITR/Streams aur global replica limits distinguish kar sakta hoon'],
    homework:'<p><b>Optional approved AWS sandbox only; billable.</b> Check current Region prices/quotas, budget alarms and IAM scope first. Use uniquely named throwaway cart tables, realistic distributed traffic and a controlled concentrated-key test. Measure throttle reason, p99, consumed units and GSI backpressure; do not overload shared production. Verify conditional duplicate and failed atomic checkout with actual data. Enable PITR, record actual restorable range, restore into a new table and compare rows; test TTL with app expiry checks. Treat live-writer migration as a separate CDC/reconciliation/cutover drill. Cleanup all owned source/restored tables, backups/exports/S3 objects, alarms/roles and optional cache/replicas; check billing. No blanket free-tier or immediate-expiry promise.</p>',
    cards:[
      {front:'Primary key can change in-place?',back:'No. Separate table with new schema, verified backfill/catch-up, controlled cutover and rollback. Full HASH+RANGE combination is unique.'},
      {front:'5KB eventual read and standard write?',back:'ceil(5/4)×0.5=1 read unit; ceil(5/1)=5 write units. Transactions use2× corresponding standard units.'},
      {front:'Hot key versus total table capacity?',back:'Physical partition designed up to3000read/1000write units/s. Distributed traffic and adaptive limits matter; cardinality alone is insufficient.'},
      {front:'Query filter saves read capacity?',back:'No. Filters apply after up to1MB evaluated page. Continue LastEvaluatedKey even on empty result; use matching keys/index.'},
      {front:'GSI versus LSI?',back:'GSI alternative HASH, later creation, eventual, separate provisioned capacity. LSI same HASH, creation-time only, strong optional, shared capacity/10GB collection limit.'},
      {front:'Batch versus transaction?',back:'Batch25puts/deletes16MB, non-atomic, retry UnprocessedItems. Transaction100distinct items4MB, atomic supported scope, token10minutes.'},
      {front:'TTL, Streams, PITR?',back:'TTL Numeric epoch seconds/background deletion; Streams24h item changes; PITR1–35days restore new table within actual time range. Different tools.'},
      {front:'MREC versus MRSC?',back:'MREC async/LWW/local transaction atomicity. MRSC strong cross-Region,3Region topology, no TTL/LSI/transactions currently; GSI eventual. Mode immutable.'}
    ]
  }]);
})();
